//! Galileo E5a primary (LFSR-generated) and secondary spreading codes.
//!
//! The E5a-I (data) and E5a-Q (pilot) primary codes are length-10230 truncated,
//! combined M-sequences generated by a pair of 14-bit LFSRs per the Galileo OS
//! SIS ICD (Issue 2.1, §3.3-3.4): base register 1 (all-ones start) XOR base
//! register 2 (per-PRN start). Feedback taps (Table 15) and base-register-2 start
//! values (Table 16 E5a-I / Table 17 E5a-Q) are factual constants of the
//! signal-in-space standard, transcribed here like the E1 memory codes in
//! [`crate::galileo_e1_codes`]. Correctness is pinned by the ICD's published
//! first-24-chip hex for every PRN (see the tests) -- the test-vector net that
//! catches any transcription or LFSR-convention error.
//!
//! Secondary (tiered) codes: E5a-I overlays the common length-20 CS20 sequence;
//! E5a-Q overlays a per-PRN length-100 CS100 sequence (ICD Tables 20-22).
//!
//! The primary codes are consumed by the `Signal` enum (Phase 1); the secondary
//! codes wait for the E5a-Q pilot / F-NAV tiering (Phase 3) — hence the targeted
//! `allow(dead_code)` on those helpers below.

/// E5a primary code length (chips): 10230 at 10.23 Mcps = 1 ms primary epoch.
pub const E5_PRIMARY_LEN: usize = 10230;

/// E5a-I secondary code length (CS20), one common 20-chip sequence (20 ms).
pub const E5A_I_SECONDARY_LEN: usize = 20;
/// E5a-Q secondary code length (CS100), per-PRN 100-chip sequence (100 ms).
#[allow(dead_code)] // Phase 3 (E5a-Q pilot)
pub const E5A_Q_SECONDARY_LEN: usize = 100;

// 14-bit base-register feedback taps (octal), ICD Table 15. E5a-I and E5a-Q
// share both registers; only base register 2's start value differs per PRN.
const E5A_REG1_TAPS: u16 = 0o40503;
const E5A_REG2_TAPS: u16 = 0o50661;

// Base register 2 start values (octal), ICD Table 16 (E5a-I), PRN n at index n-1.
// Base register 1 starts all-ones for every code.
const E5A_I_REG2_START: [u16; 50] = [
    0o30305, 0o14234, 0o27213, 0o20577, 0o23312, 0o33463, 0o15614, 0o12537, 0o01527, 0o30236,
    0o27344, 0o07272, 0o36377, 0o17046, 0o06434, 0o15405, 0o24252, 0o11631, 0o24776, 0o00630,
    0o11560, 0o17272, 0o27445, 0o31702, 0o13012, 0o14401, 0o34727, 0o22627, 0o30623, 0o27256,
    0o01520, 0o14211, 0o31465, 0o22164, 0o33516, 0o02737, 0o21316, 0o35425, 0o35633, 0o24655,
    0o14054, 0o27027, 0o06604, 0o31455, 0o34465, 0o25273, 0o20763, 0o31721, 0o17312, 0o13277,
];

// Base register 2 start values (octal), ICD Table 17 (E5a-Q), PRN n at index n-1.
const E5A_Q_REG2_START: [u16; 50] = [
    0o25652, 0o05142, 0o24723, 0o31751, 0o27366, 0o24660, 0o33655, 0o27450, 0o07626, 0o01705,
    0o12717, 0o32122, 0o16075, 0o16644, 0o37556, 0o02477, 0o02265, 0o06430, 0o25046, 0o12735,
    0o04262, 0o11230, 0o00037, 0o06137, 0o04312, 0o20606, 0o11162, 0o22252, 0o30533, 0o24614,
    0o07767, 0o32705, 0o05052, 0o27553, 0o03711, 0o02041, 0o34775, 0o05274, 0o37356, 0o16205,
    0o36270, 0o06600, 0o26773, 0o17375, 0o35267, 0o36255, 0o12044, 0o26442, 0o21621, 0o25411,
];

/// One 14-bit Fibonacci LFSR run for [`E5_PRIMARY_LEN`] chips. Output is the
/// j=R (cell 14) bit; the feedback is the parity of the tapped cells and enters
/// cell 1 as the register shifts toward higher index. Tap/start bit conventions
/// per ICD §3.4.1: feedback-tap octal bit j = a_j (j=1..14, a_0 ignored, a_14=1);
/// start-value octal bit (j-1) = s_j (so the octal *is* the cell vector).
fn lfsr_seq(taps_oct: u16, start: u16) -> Vec<u8> {
    let tapmask = (taps_oct >> 1) & 0x3FFF; // a_j placed at bit (j-1)
    let mut reg = start & 0x3FFF;
    let mut out = Vec::with_capacity(E5_PRIMARY_LEN);
    for _ in 0..E5_PRIMARY_LEN {
        out.push(((reg >> 13) & 1) as u8); // output cell j=14
        let fb = (reg & tapmask).count_ones() as u16 & 1;
        reg = ((reg << 1) | fb) & 0x3FFF; // shift up, feedback -> cell 1
    }
    out
}

/// E5a primary code at logic level (0/1) for `prn` (1..=50); `pilot` selects the
/// E5a-Q component, else E5a-I. `None` for an out-of-range PRN.
fn e5a_primary_logic(prn: u8, pilot: bool) -> Option<Vec<u8>> {
    let idx = (prn as usize).checked_sub(1)?;
    let start2 = *if pilot {
        &E5A_Q_REG2_START
    } else {
        &E5A_I_REG2_START
    }
    .get(idx)?;
    let r1 = lfsr_seq(E5A_REG1_TAPS, 0x3FFF); // base register 1: all-ones start
    let r2 = lfsr_seq(E5A_REG2_TAPS, start2);
    Some(r1.iter().zip(r2).map(|(a, b)| a ^ b).collect())
}

/// E5a primary spreading code as bipolar chips (+1/-1) for `prn` (1..=50);
/// `pilot` picks E5a-Q, else E5a-I. Logic 0 -> +1, logic 1 -> -1 (the E1
/// memory-code convention). `None` for an out-of-range PRN.
pub fn e5a_primary_code(prn: u8, pilot: bool) -> Option<Vec<i8>> {
    Some(
        e5a_primary_logic(prn, pilot)?
            .iter()
            .map(|&b| if b == 0 { 1 } else { -1 })
            .collect(),
    )
}

