/// Decode a hex secondary code into `n_bits` bipolar chips (+1/-1), MSB-first
/// (logic 0 -> +1, 1 -> -1). Trailing bits past `n_bits` (zero-padding the last
/// nibble) are dropped.
fn secondary_code(hex: &str, n_bits: usize) -> Vec<i8> {
    let mut bits = Vec::with_capacity(hex.len() * 4);
    for c in hex.chars() {
        let v = c.to_digit(16).expect("hex secondary code");
        for k in (0..4).rev() {
            bits.push(if (v >> k) & 1 == 0 { 1i8 } else { -1 });
        }
    }
    bits.truncate(n_bits);
    bits
}

/// E5a-I secondary code (CS20) as bipolar chips, common to every PRN.
#[allow(dead_code)] // Phase 3 (tiering)
pub fn e5a_i_secondary_code() -> Vec<i8> {
    secondary_code(E5A_I_SECONDARY_HEX, E5A_I_SECONDARY_LEN)
}

/// E5a-Q secondary code (CS100) as bipolar chips for `prn` (1..=50).
#[allow(dead_code)] // Phase 3 (pilot)
pub fn e5a_q_secondary_code(prn: u8) -> Option<Vec<i8>> {
    let hex = E5A_Q_SECONDARY_HEX.get((prn as usize).checked_sub(1)?)?;
    Some(secondary_code(hex, E5A_Q_SECONDARY_LEN))
}

#[cfg(test)]
mod tests {
    use super::*;

    // ICD first-24-chip hex (Table 16 E5a-I / Table 17 E5a-Q), PRN n at index
    // n-1 -- the published test vectors this whole module is validated against.
    const E5A_I_FIRST24: [&str; 50] = [
        "3CEA9D", "9D8CF1", "45D1C8", "7A0133", "64D423", "23300D", "91CEF2", "AA82DC", "F2A17D",
        "3D84AE", "446D38", "C514F2", "0C0184", "8767E0", "CB8EFF", "93EBCD", "5D55CE", "B19B7C",
        "5805FC", "F99EA1", "B23CE5", "8515E8", "436822", "30F77B", "A7D629", "9BFAC7", "18A25B",
        "69A39F", "39B27D", "454598", "F2BC62", "9DDBC6", "332827", "6E2FCA", "22C6D5", "E881D9",
        "74C4DB", "13AB03", "119323", "594886", "9F4D89", "47A3C0", "C9ED53", "334994", "1B2A30",
        "5513F3", "7831C1", "30B93A", "84D5B4", "A5029C",
    ];
    const E5A_Q_FIRST24: [&str; 50] = [
        "515537", "D67539", "58B2E5", "305914", "442710", "593CF8", "214AD7", "435EA6", "C1A7D5",
        "F0E94A", "A8C239", "2EB63B", "8F0A46", "896DD4", "0245F1", "EB0160", "ED28B3", "CB9F5B",
        "576592", "A88811", "DD3649", "B59F42", "FF81F6", "CE8128", "DCD55C", "79E450", "B63460",
        "6D562B", "3A9010", "59CD72", "C0211A", "28EB96", "D7554B", "425126", "E0DAFB", "EF79F2",
        "18085D", "D50CD8", "0447B9", "8DE877", "0D1FA0", "C9FCF7", "48116D", "840BCC", "152004",
        "0D4897", "AF6D25", "4B7593", "71BB1B", "53DA0E",
    ];

    /// Pack the first 24 logic chips MSB-first into 6 hex nibbles.
    fn first24_hex(logic: &[u8]) -> String {
        (0..6)
            .map(|nib| {
                let v = (0..4).fold(0u8, |acc, k| (acc << 1) | logic[nib * 4 + k]);
                char::from_digit(v as u32, 16).unwrap().to_ascii_uppercase()
            })
            .collect()
    }

    // The gold-standard validation: the generated code's first 24 chips must
    // equal the ICD's published hex for every PRN, both components. This pins the
    // LFSR convention (taps, start mapping, output cell, shift) and every start
    // value at once -- if any were wrong, a PRN would mismatch.
    #[test]
    fn e5a_primary_matches_icd_first_chips() {
        for prn in 1..=50u8 {
            let i = e5a_primary_logic(prn, false).unwrap();
            assert_eq!(i.len(), E5_PRIMARY_LEN, "E5a-I PRN{prn} length");
            assert_eq!(
                first24_hex(&i),
                E5A_I_FIRST24[prn as usize - 1],
                "E5a-I PRN{prn} first 24 chips"
            );
            let q = e5a_primary_logic(prn, true).unwrap();
            assert_eq!(q.len(), E5_PRIMARY_LEN, "E5a-Q PRN{prn} length");
            assert_eq!(
                first24_hex(&q),
                E5A_Q_FIRST24[prn as usize - 1],
                "E5a-Q PRN{prn} first 24 chips"
            );
        }
    }

    // A length-10230 truncated, combined M-sequence is bipolar and near-balanced.
    #[test]
    fn e5a_primary_is_bipolar_and_balanced() {
        for &pilot in &[false, true] {
            let c = e5a_primary_code(7, pilot).unwrap();
            assert_eq!(c.len(), E5_PRIMARY_LEN);
            assert!(c.iter().all(|&x| x == 1 || x == -1));
            let sum: i32 = c.iter().map(|&x| x as i32).sum();
            assert!(
                sum.abs() < 300,
                "near-balanced, got sum {sum} (pilot={pilot})"
            );
        }
    }

    #[test]
    fn e5a_secondary_codes_decode() {
        let cs20 = e5a_i_secondary_code();
        assert_eq!(cs20.len(), E5A_I_SECONDARY_LEN);
        assert!(cs20.iter().all(|&x| x == 1 || x == -1));
        for prn in 1..=50u8 {
            let cs100 = e5a_q_secondary_code(prn).unwrap();
            assert_eq!(cs100.len(), E5A_Q_SECONDARY_LEN, "PRN{prn} CS100 length");
        }
        assert!(e5a_q_secondary_code(51).is_none());
    }

    #[test]
    fn out_of_range_prn_is_none() {
        assert!(e5a_primary_code(0, false).is_none());
        assert!(e5a_primary_code(51, false).is_none());
    }
}
